/*
 * build_engine.cpp - build TensorRT engines for GPU or DLA from the ResNet10
 * ONNX model, with INT8 calibration on real frames from the target scene.
 *
 * Why: the calibration table shipped with the MMAPI sample was generated by
 * TensorRT 7 against the Caffe graph. Its tensor names do not match the ONNX
 * graph (e.g. no scale for "Layer3_block_0_Y"), so TensorRT 8.5 silently runs
 * those layers in FP16 instead of INT8 - and on DLA that costs both speed and
 * a different numeric path than the GPU engine.
 *
 *   build_engine --onnx m.onnx --out e.engine [--dla N] [--int8 frames.raw]
 *                [--cache calib.cache] [--max-frames N]
 */
#include <NvInfer.h>
#include <NvOnnxParser.h>
#include <cuda_runtime_api.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <memory>
#include <string>
#include <vector>

using namespace nvinfer1;

namespace {
class Logger : public ILogger {
    void log(Severity s, const char *msg) noexcept override {
        if (s <= Severity::kWARNING) fprintf(stderr, "[trt] %s\n", msg);
    }
} g_logger;

/* Feeds RGBA 640x368 frames, converted exactly like the runtime kernel
 * (planar RGB, x/255), so calibration sees the deployed input distribution. */
class FrameCalibrator : public IInt8EntropyCalibrator2 {
public:
    FrameCalibrator(const std::string &frames, const std::string &cache, int w, int h, int max)
        : cache_(cache), w_(w), h_(h) {
        std::ifstream f(frames, std::ios::binary);
        size_t fs = (size_t)w * h * 4;
        std::vector<unsigned char> rgba(fs);
        while (f.read((char *)rgba.data(), (std::streamsize)fs) && (int)data_.size() < max) {
            std::vector<float> chw((size_t)3 * w * h);
            for (int i = 0; i < w * h; i++)
                for (int c = 0; c < 3; c++) chw[(size_t)c * w * h + i] = rgba[(size_t)i * 4 + c] / 255.0f;
            data_.push_back(std::move(chw));
        }
        cudaMalloc(&dev_, (size_t)3 * w * h * sizeof(float));
        fprintf(stderr, "calibrator: %zu frames from %s\n", data_.size(), frames.c_str());
    }
    ~FrameCalibrator() override { cudaFree(dev_); }
    int getBatchSize() const noexcept override { return 1; }
    bool getBatch(void *bindings[], const char *[], int) noexcept override {
        if (next_ >= data_.size()) return false;
        cudaMemcpy(dev_, data_[next_++].data(), data_[0].size() * sizeof(float), cudaMemcpyHostToDevice);
        bindings[0] = dev_;
        return true;
    }
    const void *readCalibrationCache(size_t &len) noexcept override {
        std::ifstream f(cache_, std::ios::binary);
        if (!f) { len = 0; return nullptr; }
        blob_.assign(std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>());
        len = blob_.size();
        fprintf(stderr, "calibrator: reusing cache %s\n", cache_.c_str());
        return blob_.data();
    }
    void writeCalibrationCache(const void *p, size_t len) noexcept override {
        std::ofstream(cache_, std::ios::binary).write((const char *)p, (std::streamsize)len);
    }
private:
    std::string cache_;
    int w_, h_;
    std::vector<std::vector<float>> data_;
    std::vector<char> blob_;
    void *dev_ = nullptr;
    size_t next_ = 0;
};
}  // namespace

int main(int argc, char **argv)
{
    std::string onnx, out, frames, cache = "models/calib_frames.cache";
    int dla = -1, max_frames = 500;
    for (int i = 1; i + 1 < argc; i += 2) {
        std::string k = argv[i], v = argv[i + 1];
        if (k == "--onnx") onnx = v;
        else if (k == "--out") out = v;
        else if (k == "--dla") dla = atoi(v.c_str());
        else if (k == "--int8") frames = v;
        else if (k == "--cache") cache = v;
        else if (k == "--max-frames") max_frames = atoi(v.c_str());
    }
    if (onnx.empty() || out.empty()) {
        fprintf(stderr, "usage: %s --onnx M --out E [--dla N] [--int8 frames.raw] [--cache C]\n", argv[0]);
        return 2;
    }

    std::unique_ptr<IBuilder> b(createInferBuilder(g_logger));
    std::unique_ptr<INetworkDefinition> net(b->createNetworkV2(
        1U << (int)NetworkDefinitionCreationFlag::kEXPLICIT_BATCH));
    std::unique_ptr<nvonnxparser::IParser> parser(nvonnxparser::createParser(*net, g_logger));
    if (!parser->parseFromFile(onnx.c_str(), (int)ILogger::Severity::kWARNING)) return 1;

    std::unique_ptr<IBuilderConfig> cfg(b->createBuilderConfig());
    ITensor *in = net->getInput(0);
    Dims d = in->getDimensions();
    d.d[0] = 1;                                   /* static batch 1 (DLA needs static shapes) */
    IOptimizationProfile *prof = b->createOptimizationProfile();
    prof->setDimensions(in->getName(), OptProfileSelector::kMIN, d);
    prof->setDimensions(in->getName(), OptProfileSelector::kOPT, d);
    prof->setDimensions(in->getName(), OptProfileSelector::kMAX, d);
    cfg->addOptimizationProfile(prof);
    cfg->setMemoryPoolLimit(MemoryPoolType::kWORKSPACE, 256u << 20);
    cfg->setFlag(BuilderFlag::kFP16);

    std::unique_ptr<FrameCalibrator> calib;
    if (!frames.empty()) {
        cfg->setFlag(BuilderFlag::kINT8);
        calib.reset(new FrameCalibrator(frames, cache, d.d[3], d.d[2], max_frames));
        cfg->setInt8Calibrator(calib.get());
        cfg->setCalibrationProfile(prof);
    }
    if (dla >= 0) {
        cfg->setDefaultDeviceType(DeviceType::kDLA);
        cfg->setDLACore(dla);
        cfg->setFlag(BuilderFlag::kGPU_FALLBACK);
    }
    cfg->setProfilingVerbosity(ProfilingVerbosity::kDETAILED);

    std::unique_ptr<IHostMemory> plan(b->buildSerializedNetwork(*net, *cfg));
    if (!plan) { fprintf(stderr, "build failed\n"); return 1; }
    std::ofstream(out, std::ios::binary).write((const char *)plan->data(), (std::streamsize)plan->size());
    fprintf(stderr, "wrote %s (%zu bytes) for %s%s\n", out.c_str(), plan->size(),
            dla >= 0 ? "DLA" : "GPU", frames.empty() ? " FP16" : " INT8");
    return 0;
}
